    o=[[bg]*W for _ in range(H)]
    marks=[(r,c,v) for r,row in enumerate(g) for c,v in enumerate(row) if v!=bg]
    for rr in range(H):
        for cc in range(W):
            cands=[]
            for (r,c,v) in marks:
                d=(abs(rr-r),abs(cc-c))
                if max(d)<=1 and (d[1]-d[0])%2==0:
                    cands.append((max(d[0],d[1]), abs(cc-c), v))
            if len(cands)>1:
                best=min(cands)
                # tie-break: closer column distance
                win=[c for c in cands if c[0]==best[0]]
                w=min(win,key=lambda x:(x[1],win.index(x)))
                if w==best: o[rr][cc]=best[2]
            elif cands: o[rr][cc]=cands[0][2]
    return o
